import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;
    static final int SIZE = 32;
    static final int MAX_D = 64;
    static final int MAX_K = 32;

    static class Matrix {
        int[][] mat = new int[SIZE][SIZE];

        Matrix() {
            for (int i = 0; i < SIZE; i++) {
                for (int j = 0; j < SIZE; j++) {
                    mat[i][j] = 0;
                }
            }
        }

        int[] getRow(int i) {
            return mat[i];
        }

        static Matrix multiply(Matrix a, Matrix b) {
            Matrix res = new Matrix();
            for (int i = 0; i < SIZE; i++) {
                for (int j = 0; j < SIZE; j++) {
                    for (int k = 0; k < SIZE; k++) {
                        res.mat[i][j] = add(res.mat[i][j], mul(a.mat[i][k], b.mat[k][j]));
                    }
                }
            }
            return res;
        }
    }

    static int add(int a, int b) {
        return (a + b) >= MOD ? (a + b - MOD) : (a + b);
    }

    static int mul(int a, int b) {
        return (int)(((long) a * b) % MOD);
    }

    static int[] f[][] = new int[MAX_D][SIZE][SIZE];
    static int k;

    static Matrix buildMatrix(int n, int offset) {
        Matrix result = new Matrix();
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                int ni = (i == k) ? i : (i + offset) % k;
                int nj = (j == k) ? j : (j + offset) % k;
                result.mat[ni][nj] = f[n][i][j];
            }
        }
        return result;
    }

    static int sumDigits(long n) {
        int total = 0;
        while (n > 0) {
            total += n % k;
            n /= k;
        }
        return total % k;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int base = sc.nextInt();
        k = base;

        int digitCount = 0;
        long temp = n;
        while (temp > 0) {
            temp /= k;
            digitCount++;
        }

        Matrix identity = new Matrix();
        for (int i = 0; i <= k; i++) {
            identity.mat[i][i] = 1;
        }

        // Initialize f[0]
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                f[0][i][j] = 0;
            }
        }
        for (int i = 0; i <= k; i++) {
            f[0][i][0] = 1;
        }

        for (int i = 1; i < digitCount; i++) {
            // Copy previous
            for (int r = 0; r <= k; r++) {
                for (int c = 0; c <= k; c++) {
                    f[i][r][c] = f[i - 1][r][c];
                }
            }
            // Multiply by build_matrix(i - 1, j) for each j
            for (int j = 0; j < k; j++) {
                Matrix m = buildMatrix(i - 1, j);
                // Multiply f[i] by m
                int[][] newF = new int[SIZE][SIZE];
                for (int r = 0; r <= k; r++) {
                    for (int c = 0; c <= k; c++) {
                        newF[r][c] = 0;
                        for (int s = 0; s <= k; s++) {
                            newF[r][c] = add(newF[r][c], mul(f[i][r][s], m.mat[s][c]));
                        }
                    }
                }
                f[i] = newF;
            }
        }

        long current = 0;
        long power = 1;
        int remainingDigits = digitCount - 1;
        for (int i = 0; i < remainingDigits; i++) {
            power *= k;
        }

        Matrix answer = new Matrix();
        for (int i = 0; i <= k; i++) {
            answer.mat[i][i] = 1;
        }

        while (current < n) {
            // assert remainingDigits >= 0
            while (current + power <= n) {
                answer = Matrix.multiply(answer, buildMatrix(remainingDigits, sumDigits(current)));
                current += power;
            }
            power /= k;
            remainingDigits--;
        }

        int totalSum = 0;
        for (int i = 0; i <= k; i++) {
            totalSum = add(totalSum, answer.mat[k][i]);
        }
        System.out.println(totalSum);
        sc.close();
    }
}

